std::string Captured(const char* body,bool velocity=false) {
    std::string source=gpu::VertexProgramHlsl({},gpu::vehicle_pbr::kRegisters,4ull<<8,velocity);
    source.insert(source.find("\n    VOut o;"),body);
    if(velocity) {
        std::string previous=body;
        for(size_t at=0;(at=previous.find("c[",at))!=previous.npos;at+=6)previous.replace(at,2,"cprev[");
        source.insert(source.find("    return oPos;"),previous);
    }
    return source;
}
void Compile(const std::string& source,const char* profile) {
    Microsoft::WRL::ComPtr<ID3DBlob> code,errors;
    HRESULT hr=D3DCompile(source.data(),source.size(),"vehicle_pbr",nullptr,nullptr,"main",profile,
                         D3DCOMPILE_OPTIMIZATION_LEVEL3|D3DCOMPILE_WARNINGS_ARE_ERRORS,0,&code,&errors);
    if(FAILED(hr)&&errors)std::cerr<<static_cast<const char*>(errors->GetBufferPointer())<<"\n";
    assert(SUCCEEDED(hr)&&code);
}
std::string Pixel() {
    gpu::State state{}; gpu::TexInfo info[4]{};
    for(uint32_t stage=0;stage<3;++stage) {
        info[stage].kind=gpu::kTex2D;
        state.tss[stage][gpu::kTssColorOp]=4;
        state.tss[stage][gpu::kTssColorArg1]=2;
        state.tss[stage][gpu::kTssColorArg2]=stage?1:0;
        state.tss[stage][gpu::kTssAlphaOp]=2;
        state.tss[stage][gpu::kTssAlphaArg1]=stage?1:2;
    }
    auto key=gpu::MakePixelKey(state,info);
    key.car_paint=1; // legacy companion bit remains zero
    return gpu::car_paint::PixelHlsl(gpu::PixelHlsl(key),5);
}
